import type { CanonicalProduct, EquivalenceLevel, StoreId, StoreOffer } from '../types.ts';

interface PriceSeed {
  base: number;
  card?: number;
  promo?: string;
  altLabel?: string;
  eqLevel?: EquivalenceLevel;
}

const CARD_META: Partial<Record<StoreId, { cardId: StoreOffer['cardId']; program: string }>> = {
  lidl: { cardId: 'lidl_plus', program: 'Lidl Plus' },
  kaufland: { cardId: 'kaufland_card', program: 'Kaufland Card' },
  carrefour: { cardId: 'card_connect', program: 'Card CONNECT' },
  mega_image: { cardId: 'card_connect', program: 'Card CONNECT' },
  auchan: { cardId: 'myclub', program: 'MyCLUB' },
  penny: { cardId: 'penny_card', program: 'PENNY Card' },
  sezamo: { cardId: 'sezamo_xtra', program: 'Sezamo Xtra' },
};

function buildOffers(
  seeds: Record<StoreId, PriceSeed>,
  isPrivateLabel = false
): Record<StoreId, StoreOffer> {
  const result = {} as Record<StoreId, StoreOffer>;
  (Object.keys(seeds) as StoreId[]).forEach((storeId) => {
    const seed = seeds[storeId];
    const cardMeta = CARD_META[storeId];
    const eqLevel: EquivalenceLevel =
      seed.eqLevel ?? (isPrivateLabel ? 4 : seed.altLabel ? 3 : 1);
    result[storeId] = {
      storeId,
      basePrice: seed.base,
      cardPrice: seed.card,
      cardId: seed.card !== undefined ? cardMeta?.cardId : undefined,
      cardProgram: seed.card !== undefined ? cardMeta?.program : undefined,
      promoLabel: seed.promo,
      matchKind: eqLevel === 4 || isPrivateLabel ? 'Marcă proprie / Alternativă' : 'Exact',
      equivalenceLevel: eqLevel,
      variantLabel: seed.altLabel,
    };
  });
  return result;
}

function buildEan13FromId(id: string): string {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = (hash * 31 + id.charCodeAt(i)) >>> 0;
  }
  const prefix = '594' + String(hash).padStart(9, '0').slice(-9);
  return buildEan13(prefix);
}

function buildEan13(prefix12: string): string {
  const digits = prefix12.replace(/\D/g, '').slice(0, 12).padStart(12, '5');
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += Number(digits[i]) * (i % 2 === 0 ? 1 : 3);
  }
  const check = (10 - (sum % 10)) % 10;
  return `${digits}${check}`;
}

